#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

banner "SMTP setup — low-stock email (POS backend)"

API="http://localhost:4000/api/v1"

# ── Stage 1 — choose the provider ──────────────────────────────────────────
stage "Choose your SMTP provider"
say "All three speak plain SMTP with STARTTLS on port 587. Pick per run:"
note "  1) Mailtrap — SANDBOX: full real pipeline, messages land in a web inbox,"
note "     delivered to nobody. Zero risk. Best for dev + CI. (recommended)"
note "  2) Gmail — real inbox via a personal account app password. Fastest"
note "     'it really arrived' proof; From gets rewritten to your address."
note "  3) Brevo — transactional relay (300/day free). The production shape."
while :; do
  ask PROVIDER_NUM "Choose 1, 2 or 3:"
  case "$PROVIDER_NUM" in
    1) PROVIDER="mailtrap"; break ;;
    2) PROVIDER="gmail";    break ;;
    3) PROVIDER="brevo";    break ;;
    *) warn "Enter 1, 2 or 3." ;;
  esac
done

# ── Stage 2 — get credentials from the provider ───────────────────────────
stage "Get your SMTP credentials"
SMTP_PORT="587"

if [[ "$PROVIDER" == "mailtrap" ]]; then
  open_url "https://mailtrap.io"
  step "Sign in (or sign up — free tier is fine) and open 'Email Testing' → Inboxes."
  step "Open the default inbox (or create one), then the 'SMTP' settings tab."
  step "Copy the Username and Password shown there (host is smtp.mailtrap.io)."
  SMTP_HOST="smtp.mailtrap.io"
  ask SMTP_USERNAME "Paste the Mailtrap username:"
  ask_secret SMTP_PASSWORD "Paste the Mailtrap password:"
  note "Yesterday's probe stores still have low stock — they'll feed this inbox."
elif [[ "$PROVIDER" == "gmail" ]]; then
  open_url "https://myaccount.google.com/security"
  step "If 2-Step Verification is OFF, turn it on first (app passwords need it)."
  open_url "https://myaccount.google.com/apppasswords"
  step "Create an app password named 'POS backend' and copy the 16 characters."
  step "Your username is your full Gmail address."
  SMTP_HOST="smtp.gmail.com"
  ask SMTP_USERNAME "Your full Gmail address:"
  ask_secret SMTP_PASSWORD "Paste the app password (spaces included are fine):"
  warn "Gmail rewrites the From: address to yours — expect the sender to be you."
else
  open_url "https://app.brevo.com"
  step "Sign in (or sign up), then open your name → 'SMTP & API'."
  step "Click 'Create a new SMTP key' and copy it."
  step "Your username is the email you signed up with. Host: smtp-relay.brevo.com."
  SMTP_HOST="smtp-relay.brevo.com"
  ask SMTP_USERNAME "Your Brevo login email:"
  ask_secret SMTP_PASSWORD "Paste the SMTP key:"
fi

# ── Stage 3 — write the SMTP block into .env ──────────────────────────────
stage "Write the SMTP block into $ENV_FILE"
say "Sanitizing pasted values (Git Bash can smuggle an invisible carriage return)."
SMTP_HOST="${SMTP_HOST//$'\r'/}"
SMTP_USERNAME="${SMTP_USERNAME//$'\r'/}"
SMTP_PASSWORD="${SMTP_PASSWORD//$'\r'/}"
say "Nine SPRING_MAIL_* variables — host, port, credentials, auth, STARTTLS,"
say "and the finite timeouts from the PR review."
write_env SPRING_MAIL_HOST "$SMTP_HOST"
write_env SPRING_MAIL_PORT "$SMTP_PORT"
write_env SPRING_MAIL_USERNAME "$SMTP_USERNAME"
write_env SPRING_MAIL_PASSWORD "$SMTP_PASSWORD"
write_env SPRING_MAIL_PROPERTIES_MAIL_SMTP_AUTH "true"
write_env SPRING_MAIL_PROPERTIES_MAIL_SMTP_STARTTLS_ENABLE "true"
write_env SPRING_MAIL_PROPERTIES_MAIL_SMTP_CONNECTIONTIMEOUT "5000"
write_env SPRING_MAIL_PROPERTIES_MAIL_SMTP_TIMEOUT "10000"
write_env SPRING_MAIL_PROPERTIES_MAIL_SMTP_WRITETIMEOUT "10000"
note "Without AUTH/STARTTLS the relay rejects you: '530 5.7.0 Authentication Required'."
if git check-ignore -q "$ENV_FILE" 2>/dev/null; then
  note "$ENV_FILE is gitignored — credentials will never be committed."
else
  warn "$ENV_FILE is NOT gitignored — check .gitignore before pushing!"
fi

# ── Stage 4 — compose wiring (you type it) ─────────────────────────────────
stage "Wire .env into the container (you type this)"
say "docker-compose.yml only passes an explicit environment list — SPRING_MAIL_*"
say "never reaches the app. Add env_file so every .env var flows in, and stays"
say "genuinely ABSENT when commented out (fail-soft preserved)."
step "Open docker-compose.yml and add this under the pos-backend service"
step "(same indent level as 'environment:'):"
printf '\n  %spos-backend:%s\n' "$BOLD" "$RESET"
printf '  %senv_file:%s\n' "$BOLD" "$RESET"
printf '  %s  - .env%s\n' "$BOLD" "$RESET"
printf '\n'
note "Explicit 'environment:' entries still win over env_file — no conflicts."
note "Extra .env vars (POS_DB_*) will ride along into the container; harmless in dev."
pause "Type it, save, then press Enter"
if grep -A2 "env_file:" docker-compose.yml >/dev/null 2>&1; then
  printf '  %s✓ env_file found in docker-compose.yml%s\n' "$GREEN" "$RESET"
else
  warn "Couldn't find env_file: in docker-compose.yml — the container won't see SPRING_MAIL_*."
fi

# ── Stage 5 — recreate the stack and verify boot ──────────────────────────
stage "Recreate the stack"
say "A compose config change forces a recreate — env flows into the new container."
docker compose up -d >/dev/null 2>&1 || { warn "docker compose up failed — is Docker Desktop running?"; exit 1; }
say "Waiting for the app to answer on :4000..."
up=1
for _ in $(seq 1 30); do
  code=$(curl -s -o /dev/null -w "%{http_code}" "$API/stores" 2>/dev/null || true)
  if [[ "$code" == "401" ]]; then up=0; break; fi
  sleep 3
done
if [[ "$up" == "0" ]]; then
  printf '  %s✓ app is up (security answered 401 without a token)%s\n' "$GREEN" "$RESET"
else
  warn "App didn't answer in 90s — check: docker compose logs pos-backend"
fi
note "Fail-soft check: with mail configured, no 'SMTP not configured' WARN on scan."

# ── Stage 6 — live-fire test ──────────────────────────────────────────────
stage "Live-fire: prove the email path end to end"
say "The scan fires at 09:00 by default — we override the cron to ~2 minutes"
say "from now, fire once, then revert."
if ! confirm "Run the live-fire test now?"; then
  note "Skipped — your email path is configured; the next 09:00 scan will use it."
else
  LOWSTOCK_ZONE=$(_existing APP_INVENTORY_LOWSTOCK_ZONE || printf '%s' "Africa/Lagos")
  CRON_MIN=$(TZ="$LOWSTOCK_ZONE" date -d "+2 minutes" +%M)
  CRON_HOUR=$(TZ="$LOWSTOCK_ZONE" date -d "+2 minutes" +%H)
  write_env APP_INVENTORY_LOWSTOCK_CRON "0 $CRON_MIN $CRON_HOUR * * *"
  note "Cron set to 0 $CRON_MIN $CRON_HOUR — app restarts on the env change."
  docker compose up -d --force-recreate pos-backend >/dev/null 2>&1 || true

  if [[ "$PROVIDER" != "mailtrap" ]] && confirm "Seed a REAL-inbox test (signs your email up as a store admin, stocks 0 items)?"; then
    ask RECIPIENT_EMAIL "Your real email (the alert lands here):"
    RECIPIENT_EMAIL="${RECIPIENT_EMAIL//$'\r'/}"
    say "Seeding via the API (takes a few seconds)..."
    SEED_OK=1
    json_val() { printf '%s' "$1" | grep -o "\"$2\":\"[^\"]*" | head -n1 | cut -d'"' -f4 || true; }
    curl -s -o /dev/null -X POST "$API/auth/signup" -H "Content-Type: application/json" \
      -d '{"fullName":"Wizard Smoke Owner","email":"'"$RECIPIENT_EMAIL"'","password":"Password123!","phone":"+2348099999999"}' || true
    HIS_LOGIN=$(curl -s -X POST "$API/auth/login" -H "Content-Type: application/json" \
      -d '{"email":"'"$RECIPIENT_EMAIL"'","password":"Password123!"}' || true)
    HIS_TOKEN=$(json_val "$HIS_LOGIN" accessToken)
    HIS_ID=$(json_val "$HIS_LOGIN" publicId)
    ADMIN_LOGIN=$(curl -s -X POST "$API/auth/login" -H "Content-Type: application/json" \
      -d '{"email":"admin@devtunde.com","password":"Password123!"}' || true)
    ADMIN_TOKEN=$(json_val "$ADMIN_LOGIN" accessToken)
    ADMIN_ID=$(json_val "$ADMIN_LOGIN" publicId)
    if [[ -n "$HIS_TOKEN" && -n "$HIS_ID" && -n "$ADMIN_TOKEN" && -n "$ADMIN_ID" ]]; then
      STORE=$(curl -s -X POST "$API/stores" -H "Content-Type: application/json" \
        -H "Authorization: Bearer $ADMIN_TOKEN" \
        -d '{"brand":"Wizard Smoke Store '$RANDOM'","storeType":"KIOSK","storeAdminPublicId":"'"$HIS_ID"'","contact":{"address":"Wizard Way","phone":"08012345678","email":"wizard-smoke-'$RANDOM'@devtunde.com"}}' || true)
      STORE_ID=$(json_val "$STORE" publicId)
      CAT=$(curl -s -X POST "$API/categories" -H "Content-Type: application/json" \
        -H "Authorization: Bearer $ADMIN_TOKEN" -d '{"name":"Wizard Smoke Category '$RANDOM'"}' || true)
      CAT_ID=$(json_val "$CAT" publicId)
      PROD=$(curl -s -X POST "$API/products/store/$STORE_ID" -H "Content-Type: application/json" \
        -H "Authorization: Bearer $HIS_TOKEN" \
        -d '{"name":"Wizard Smoke Milk","sku":"SKU-WIZ-'$RANDOM'","description":"Wizard","brand":"DairyCo","image":"https://cdn.devtunde.com/milk.png","categoryPublicId":"'"$CAT_ID"'","mrp":1000,"sellingPrice":900}' || true)
      PROD_ID=$(json_val "$PROD" publicId)
      if [[ -n "$STORE_ID" && -n "$CAT_ID" && -n "$PROD_ID" ]]; then
        curl -s -o /dev/null -X POST "$API/stores/$STORE_ID/inventory" -H "Content-Type: application/json" \
          -H "Authorization: Bearer $HIS_TOKEN" \
          -d '{"productPublicId":"'"$PROD_ID"'","quantity":0,"lowStockThreshold":10}' || true
        printf '  %s✓ seeded: your store is stocked at 0 — OUT tier%s\n' "$GREEN" "$RESET"
        SEED_OK=0
      fi
    fi
    if [[ "$SEED_OK" == "1" ]]; then
      warn "Seeding failed part-way — the existing probe stores still feed the scan."
    fi
  fi

  say "Waiting ~2.5 minutes for the cron to fire (success is QUIET — no log line):"
  say "the inbox is the proof; failures appear as WARN in the app log."
  pause "Come back after the fire time; press Enter to check results"
  echo
  say "Recent mail-related log lines (empty means no WARN — good sign):"
  docker compose logs pos-backend --since 4m 2>&1 | grep -iE "low.stock|mail|smtp" | tail -n 15 || note "(no mail-related warnings)"
  if [[ "$PROVIDER" == "mailtrap" ]]; then
    open_url "https://mailtrap.io"
    step "Open your inbox — the probe stores' alerts (and yours, if seeded) are there."
  else
    step "Check $RECIPIENT_EMAIL — subject: 'Low stock alert — Wizard Smoke Store ...'"
    note "Fake probe-store addresses may bounce asynchronously; that's expected."
  fi

  if confirm "Revert the temporary cron now (back to the 09:00 default)?"; then
    sed -i '/^APP_INVENTORY_LOWSTOCK_CRON=/d' "$ENV_FILE"
    docker compose up -d --force-recreate pos-backend >/dev/null 2>&1 || true
    printf '  %s✓ cron reverted to the yml default (09:00 Africa/Lagos)%s\n' "$GREEN" "$RESET"
  else
    warn "APP_INVENTORY_LOWSTOCK_CRON still set in $ENV_FILE — delete that line later."
  fi
fi

finish
